import { Subclass } from "@/interfaces/Subclass";

/**
 * `features` is every named subclassFeature entry 5etools tracks for this
 * subclass, in level order. A few subclasses (e.g. Fighter's Arcane
 * Archer) have a feature that itself grants a menu of further named
 * sub-options (Arcane Shot options, Metamagic, invocations, maneuvers,
 * etc.) - those live under 5etools' separate "optionalfeature" data
 * category, not "subclassFeature", so they aren't broken out as
 * individual `features` entries here; the umbrella feature's
 * description explains what the choice is, just not each option's text.
 */
export const ClericSubclasses: Subclass[] = [
    {
        name: "Ambition Domain (PSA)",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Bontu has fully embraced this dictum, and though she expends little effort in teaching it, she surely leads by example. Her viziers subtly plant the seeds that flower into the ambition the God-Pharaoh desires. Through insinuation, they remind acolytes and initiates alike that achieving one's place in the afterlife at the expense of others is not shameful, but is proof of the initiate's determination and drive. Nothing is more important than that drive, they suggest—not the bonds of a crop, not friendship or love. Not even devotion to a deity.",
        features: [
            { name: "Warding Flare", level: 1, description: "When you choose this domain at 1st level, you can interpose divine light between yourself and an attacking enemy. When you are attacked by a creature within 30 feet of you that you can see, you can use your reaction to impose disadvantage on the attack roll, causing light to flare before the attacker before it hits or misses. An attacker that can't be blinded is immune to this feature.\nYou can use this feature a number of times equal to your Wisdom modifier (a minimum of once). You regain all expended uses when you finish a long rest." },
            { name: "Channel Divinity: Invoke Duplicity", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to create an illusory duplicate of yourself.\nAs an action, you create a perfect illusion of yourself that lasts for 1 minute, or until you lose your concentration (as if you were concentration on a spell). The illusion appears in an unoccupied space that you can see within 30 feet of you. As a bonus action on your turn, you can move the illusion up to 30 feet to a space you can see, but it must remain within 120 feet of you.\nFor the duration, you can cast spells as though you were in the illusion's space, but you must use your own senses. Additionally, when both you and your illusion are within 5 feet of a creature that can see the illusion, you have advantage on attack rolls against that creature, given how distracting the illusion is to the target." },
            { name: "Ambition Domain (PSA)", level: 3, description: "The worthy shall strive for greatness—supremacy in life leads to supremacy in the afterlife.\nBontu has fully embraced this dictum, and though she expends little effort in teaching it, she surely leads by example. Her viziers subtly plant the seeds that flower into the ambition the God-Pharaoh desires. Through insinuation, they remind acolytes and initiates alike that achieving one's place in the afterlife at the expense of others is not shameful, but is proof of the initiate's determination and drive. Nothing is more important than that drive, they suggest—not the bonds of a crop, not friendship or love. Not even devotion to a deity.\nAt each indicated cleric level, add the listed spells to your spells prepared.\nAmbition Domain Spells\n1st | bane, disguise self\n3rd | mirror image, ray of enfeeblement\n5th | bestow curse, vampiric touch\n7th | death ward, dimension door\n9th | dominate person, modify memory" },
            { name: "Channel Divinity: Invoke Duplicity", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to create an illusory duplicate of yourself.\nAs an action, you create a perfect illusion of yourself that lasts for 1 minute, or until you lose your concentration (as if you were concentration on a spell). The illusion appears in an unoccupied space that you can see within 30 feet of you. As a bonus action on your turn, you can move the illusion up to 30 feet to a space you can see, but it must remain within 120 feet of you.\nFor the duration, you can cast spells as though you were in the illusion's space, but you must use your own senses. Additionally, when both you and your illusion are within 5 feet of a creature that can see the illusion, you have advantage on attack rolls against that creature, given how distracting the illusion is to the target." },
            { name: "Channel Divinity: Cloak of Shadows", level: 6, description: "Starting at 6th level, you can use your Channel Divinity to vanish. As an action, you become invisible until the end of your next turn. You become visible if you attack or cast a spell." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Potent Spellcasting feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Potent Spellcasting", level: 8, description: "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip." },
            { name: "Improved Duplicity", level: 17, description: "At 17th level, you can create up to four duplicates of yourself, instead of one, when you use Invoke Duplicity. As a bonus action on your turn, you can move any number of them up to 30 feet, to a maximum range of 120 feet." },
        ],
    },
    {
        name: "Arcana Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Magic is an energy that suffuses the multiverse and that fuels both destruction and creation. Gods of the Arcana domain know the secrets and potential of magic intimately. For some of these gods, magical knowledge is a great responsibility that comes with a special understanding of the nature of reality. Other gods of Arcana see magic as pure power, to be used as its wielder sees fit.",
        features: [
            { name: "Arcane Initiate", level: 1, description: "When you choose this domain at 1st level, you gain proficiency in the Arcana skill, and you gain two cantrips of your choice from the wizard spell list. For you, these cantrips count as cleric cantrips." },
            { name: "Channel Divinity: Arcane Abjuration", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to abjure otherworldly creatures.\nAs an action, you present your holy symbol, and one celestial, elemental, fey, or fiend of your choice that is within 30 feet of you must make a Wisdom saving throw, provided that the creature can see or hear you. If the creature fails its saving throw, it is turned for 1 minute or until it takes any damage.\nA turned creature must spend its turns trying to move as far away from you as it can, and it can't willingly end its move in a space within 30 feet of you. It also can't take reactions. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If there's nowhere to move, then the creature can use the Dodge action.\nAfter you reach 5th level, when a creature fails its saving throw against your Arcane Abjuration feature, the creature is banished for 1 minute (as in the banishment spell, no concentration required) if it isn't on its plane of origin, and its challenge rating is at or below a certain threshold, as shown below.\nArcane Banishment\n5th | 1/2 or lower\n8th | 1 or lower\n11th | 2 or lower\n14th | 3 or lower\n17th | 4 or lower" },
            { name: "Arcana Domain", level: 3, description: "Magic is an energy that suffuses the multiverse and that fuels both destruction and creation. Gods of the Arcana domain know the secrets and potential of magic intimately. For some of these gods, magical knowledge is a great responsibility that comes with a special understanding of the nature of reality. Other gods of Arcana see magic as pure power, to be used as its wielder sees fit.\nThe gods of this domain are often associated with knowledge, as learning and arcane power tend to go hand-in-hand. In the Realms, deities of this domain include Azuth and Mystra, as well as Corellon Larethian of the elven pantheon. In other worlds, this domain includes Hecate, Math Mathonwy, and Isis; the triple moon gods of Solinari, Lunitari, and Nuitari of Krynn; and Boccob, Vecna, and Wee Jas of Greyhawk.\nAt each indicated cleric level, add the listed spells to your spells prepared. They do not count towards your limit.\nArcana Domain Spells\n1st | detect magic, magic missile\n3rd | magic weapon, Nystul's magic aura\n5th | dispel magic, magic circle\n7th | arcane eye, Leomund's secret chest\n9th | planar binding, teleportation circle" },
            { name: "Channel Divinity: Arcane Abjuration", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to abjure otherworldly creatures.\nAs an action, you present your holy symbol, and one celestial, elemental, fey, or fiend of your choice that is within 30 feet of you must make a Wisdom saving throw, provided that the creature can see or hear you. If the creature fails its saving throw, it is turned for 1 minute or until it takes any damage.\nA turned creature must spend its turns trying to move as far away from you as it can, and it can't willingly end its move in a space within 30 feet of you. It also can't take reactions. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If there's nowhere to move, then the creature can use the Dodge action.\nAfter you reach 5th level, when a creature fails its saving throw against your Arcane Abjuration feature, the creature is banished for 1 minute (as in the banishment spell, no concentration required) if it isn't on its plane of origin, and its challenge rating is at or below a certain threshold, as shown below.\nArcane Banishment\n5th | 1/2 or lower\n8th | 1 or lower\n11th | 2 or lower\n14th | 3 or lower\n17th | 4 or lower" },
            { name: "Spell Breaker", level: 6, description: "Starting at 6th level, when you restore hit points to an ally with a spell of 1st level or higher, you can also end one spell of your choice on that creature. The level of the spell you end must be equal to or lower than the level of the spell slot you use to cast the healing spell." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Potent Spellcasting feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Potent Spellcasting", level: 8, description: "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip." },
            { name: "Arcane Mastery", level: 17, description: "At 17th level, you choose four spells from the Wizard spell list, one from each of the following levels: 6th, 7th, 8th, and 9th. You add them to your list of domain spells. Like your other domain spells, they are always prepared and count as cleric spells for you." },
        ],
    },
    {
        name: "Death Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The Death domain is concerned with the forces that cause death, as well as the negative energy that gives rise to undead creatures. Deities such as Chemosh, Myrkul, and Wee Jas are patrons of necromancers, death knights, liches, mummy lords, and vampires. Gods of the Death domain also embody murder (Anubis, Bhaal, and Pyremius), pain (Iuz or Loviatar), disease or poison (Incabulos, Talona, or Morgion), and the underworld (Hades and Hel).",
        features: [
            { name: "Bonus Proficiency", level: 1, description: "When the cleric chooses this domain at 1st level, he or she gains proficiency with martial weapons." },
            { name: "Reaper", level: 1, description: "At 1st level, the cleric learns one necromancy cantrip of his or her choice from any spell list. When the cleric casts a necromancy cantrip that normally targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other." },
            { name: "Channel Divinity: Touch of Death", level: 2, description: "Starting at 2nd level, the cleric can use Channel Divinity to destroy another creature's life force by touch.\nWhen the cleric hits a creature with a melee attack, the cleric can use Channel Divinity to deal extra necrotic damage to the target. The damage equals 5 + twice his or her cleric level." },
            { name: "Channel Divinity: Touch of Death", level: 3, description: "Starting at 2nd level, the cleric can use Channel Divinity to destroy another creature's life force by touch.\nWhen the cleric hits a creature with a melee attack, the cleric can use Channel Divinity to deal extra necrotic damage to the target. The damage equals 5 + twice his or her cleric level." },
            { name: "Death Domain", level: 3, description: "The Death domain is concerned with the forces that cause death, as well as the negative energy that gives rise to undead creatures. Deities such as Chemosh, Myrkul, and Wee Jas are patrons of necromancers, death knights, liches, mummy lords, and vampires. Gods of the Death domain also embody murder (Anubis, Bhaal, and Pyremius), pain (Iuz or Loviatar), disease or poison (Incabulos, Talona, or Morgion), and the underworld (Hades and Hel).\nAt each indicated cleric level, add the listed spells to your spells prepared. They do not count towards your limit.\nDeath Domain Spells\n1st | false life, ray of sickness\n3rd | blindness/deafness, ray of enfeeblement\n5th | animate dead, vampiric touch\n7th | blight, death ward\n9th | antilife shell, cloudkill" },
            { name: "Inescapable Destruction", level: 6, description: "Starting at 6th level, the cleric's ability to channel negative energy becomes more potent. Necrotic damage dealt by the character's cleric spells and Channel Divinity options ignores resistance to necrotic damage." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, the cleric gains the ability to infuse his or her weapon strikes with necrotic energy. Once on each of the cleric's turns when he or she hits a creature with a weapon attack, the cleric can cause the attack to deal an extra 1d8 necrotic damage to the target. When the cleric reaches 14th level, the extra damage increases to 2d8." },
            { name: "Improved Reaper", level: 17, description: "Starting at 17th level, when the cleric casts a Necromancy spell of 1st through 5th-level that targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other. If the spell consumes its material components, the cleric must provide them for each target." },
        ],
    },
    {
        name: "Forge Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The gods of the forge are patrons of artisans who work with metal, from a humble blacksmith who keeps a village in horseshoes and plow blades to the mighty elf artisan whose diamond-tipped arrows of mithral have felled demon lords. The gods of the forge teach that, with patience and hard work, even the most intractable metal can be transformed from a lump of ore to a beautifully wrought object. Clerics of these deities search for objects lost to the forces of darkness, liberate mines overrun by orcs, and uncover rare and wondrous materials necessary to create potent magic items. Followers of these gods take great pride in their work, and they are willing to craft and use heavy armor and powerful weapons to protect them. Deities of this domain include Gond, Reorx, Onatar, Moradin, Hephaestus, and Goibhniu.",
        features: [
            { name: "Blessing of the Forge", level: 1, description: "At 1st level, you gain the ability to imbue magic into a weapon or armor. At the end of a long rest, you can touch one nonmagical object that is a suit of armor or a simple or martial weapon. Until the end of your next long rest or until you die, the object becomes a magic item, granting a +1 bonus to AC if it's armor or a +1 bonus to attack and damage rolls if it's a weapon.\nOnce you use this feature, you can't use it again until you finish a long rest." },
            { name: "Bonus Proficiency", level: 1, description: "When you choose this domain at 1st level, you gain proficiency with heavy armor and smith's tools." },
            { name: "Channel Divinity: Artisan's Blessing", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to create simple items.\nYou conduct an hour-long ritual that crafts a nonmagical item that must include some metal: a simple or martial weapon, a suit of armor, ten pieces of ammunition, a set of tools, or another metal object (see chapter 5, \"Equipment,\" in the Player's Handbook for examples of these items). The creation is completed at the end of the hour, coalescing in an unoccupied space of your choice on a surface within 5 feet of you.\nThe thing you create can be something that is worth no more than 100 gp. As part of this ritual, you must lay out metal, which can include coins, with a value equal to the creation. The metal irretrievably coalesces and transforms into the creation at the ritual's end, magically forming even nonmetal parts of the creation. The ritual can create a duplicate of a nonmagical item that contains metal, such as a key, if you possess the original during the ritual." },
            { name: "Channel Divinity: Artisan's Blessing", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to create simple items.\nYou conduct an hour-long ritual that crafts a nonmagical item that must include some metal: a simple or martial weapon, a suit of armor, ten pieces of ammunition, a set of tools, or another metal object (see chapter 5, \"Equipment,\" in the Player's Handbook for examples of these items). The creation is completed at the end of the hour, coalescing in an unoccupied space of your choice on a surface within 5 feet of you.\nThe thing you create can be something that is worth no more than 100 gp. As part of this ritual, you must lay out metal, which can include coins, with a value equal to the creation. The metal irretrievably coalesces and transforms into the creation at the ritual's end, magically forming even nonmetal parts of the creation. The ritual can create a duplicate of a nonmagical item that contains metal, such as a key, if you possess the original during the ritual." },
            { name: "Forge Domain", level: 3, description: "The gods of the forge are patrons of artisans who work with metal, from a humble blacksmith who keeps a village in horseshoes and plow blades to the mighty elf artisan whose diamond-tipped arrows of mithral have felled demon lords. The gods of the forge teach that, with patience and hard work, even the most intractable metal can be transformed from a lump of ore to a beautifully wrought object. Clerics of these deities search for objects lost to the forces of darkness, liberate mines overrun by orcs, and uncover rare and wondrous materials necessary to create potent magic items. Followers of these gods take great pride in their work, and they are willing to craft and use heavy armor and powerful weapons to protect them. Deities of this domain include Gond, Reorx, Onatar, Moradin, Hephaestus, and Goibhniu.\nAt each indicated cleric level, add the listed spells to your spells prepared.\nForge Domain Spells\n1st | identify, searing smite\n3rd | heat metal, magic weapon\n5th | elemental weapon, protection from energy\n7th | fabricate, wall of fire\n9th | animate objects, creation" },
            { name: "Soul of the Forge", level: 6, description: "Starting at 6th level, your mastery of the forge grants you special abilities:\n- You gain resistance to fire damage.\n- While wearing heavy armor, you gain a +1 bonus to AC." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with the fiery power of the forge. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 fire damage to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Saint of Forge and Fire", level: 17, description: "At 17th level, your blessed affinity with fire and metal becomes more powerful:\n- You gain immunity to fire damage,\n- While wearing heavy armor, you have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks." },
        ],
    },
    {
        name: "Grave Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Gods of the grave watch over the line between life and death. To these deities, death and the afterlife are a foundational part of the multiverse. To desecrate the peace of the dead is an abomination. Deities of the grave include Kelemvor, Wee Jas, the ancestral spirits of the Undying Court, Hades, Anubis, and Osiris. Followers of these deities seek to put wandering spirits to rest, destroy the undead, and ease the suffering of the dying. Their magic also allows them to stave off death for a time, particularly for a person who still has some great work to accomplish in the world. This is a delay of death, not a denial of it, for death will eventually get its due.",
        features: [
            { name: "Circle of Mortality", level: 1, description: "At 1st level, you gain the ability to manipulate the line between life and death. When you would normally roll one or more dice to restore hit points with a spell to a creature at 0 hit points, you instead use the highest number possible for each die.\nIn addition, you learn the spare the dying cantrip, which doesn't count against the number of cleric cantrips you know. For you, it has a range of 30 feet, and you can cast it as a bonus action." },
            { name: "Eyes of the Grave", level: 1, description: "At 1st level, you gain the ability to occasionally sense the presence of the undead, whose existence is an insult to the natural cycle of life. As an action, you can open your awareness to magically detect undead. Until the end of your next turn, you know the location of any undead within 60 feet of you that isn't behind Cover and that isn't protected from divination magic. This sense doesn't tell you anything about a creature's capabilities or identity.\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a long rest." },
            { name: "Channel Divinity: Path to the Grave", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to mark another creature's life force for termination.\nAs an action, you choose one creature you can see within 30 feet of you, cursing it until the end of your next turn. The next time you or an ally of yours hits the cursed creature with an attack, the creature has vulnerability to all of that attack's damage, and then the curse ends." },
            { name: "Channel Divinity: Path to the Grave", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to mark another creature's life force for termination.\nAs an action, you choose one creature you can see within 30 feet of you, cursing it until the end of your next turn. The next time you or an ally of yours hits the cursed creature with an attack, the creature has vulnerability to all of that attack's damage, and then the curse ends." },
            { name: "Grave Domain", level: 3, description: "Gods of the grave watch over the line between life and death. To these deities, death and the afterlife are a foundational part of the multiverse. To desecrate the peace of the dead is an abomination. Deities of the grave include Kelemvor, Wee Jas, the ancestral spirits of the Undying Court, Hades, Anubis, and Osiris. Followers of these deities seek to put wandering spirits to rest, destroy the undead, and ease the suffering of the dying. Their magic also allows them to stave off death for a time, particularly for a person who still has some great work to accomplish in the world. This is a delay of death, not a denial of it, for death will eventually get its due.\nGrave Domain Spells\n1st | bane, false life\n3rd | gentle repose, ray of enfeeblement\n5th | revivify, vampiric touch\n7th | blight, death ward\n9th | antilife shell, raise dead" },
            { name: "Sentinel at Death's Door", level: 6, description: "At 6th level, you gain the ability to impede death's progress. As a reaction when you or a creature you can see within 30 feet of you suffers a critical hit, you can turn that hit into a normal hit. Any effects triggered by a critical hit are canceled.\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a long rest." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Potent Spellcasting feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Potent Spellcasting", level: 8, description: "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip." },
            { name: "Keeper of Souls", level: 17, description: "Starting at 17th level, you can seize a trace of vitality from a parting soul and use it to heal the living. When an enemy you can see dies within 60 feet of you, you or one creature of your choice that is within 60 feet of you regains hit points equal to the enemy's number of Hit Dice. You can use this feature only if you aren't incapacitated. Once you use it, you can't do so again until the start of your next turn." },
        ],
    },
    {
        name: "Knowledge Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The gods of knowledge—including Oghma, Boccob, Gilean, Aureon, and Thoth—value learning and understanding above all. Some teach that knowledge is to be gathered and shared in libraries and universities, or promote the practical knowledge of craft and invention. Some deities hoard knowledge and keep its secrets to themselves. And some promise their followers that they will gain tremendous power if they unlock the secrets of the multiverse. Followers of these gods study esoteric lore, collect old tomes, delve into the secret places of the earth, and learn all they can. Some gods of knowledge promote the practical knowledge of craft and invention, including smith deities like Gond, Reorx, Onatar, Moradin, Hephaestus, and Goibhniu.",
        features: [
            { name: "Blessings of Knowledge", level: 1, description: "At 1st level, you learn two languages of your choice. You also become proficient in your choice of two of the following skills: Arcana, History, Nature, or Religion.\nYour proficiency bonus is doubled for any ability check you make that uses either of those skills." },
            { name: "Channel Divinity: Knowledge of the Ages", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to tap into a divine well of knowledge. As an action, you choose one skill or tool. For 10 minutes, you have proficiency with the chosen skill or tool." },
            { name: "Channel Divinity: Knowledge of the Ages", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to tap into a divine well of knowledge. As an action, you choose one skill or tool. For 10 minutes, you have proficiency with the chosen skill or tool." },
            { name: "Knowledge Domain", level: 3, description: "The gods of knowledge—including Oghma, Boccob, Gilean, Aureon, and Thoth—value learning and understanding above all. Some teach that knowledge is to be gathered and shared in libraries and universities, or promote the practical knowledge of craft and invention. Some deities hoard knowledge and keep its secrets to themselves. And some promise their followers that they will gain tremendous power if they unlock the secrets of the multiverse. Followers of these gods study esoteric lore, collect old tomes, delve into the secret places of the earth, and learn all they can. Some gods of knowledge promote the practical knowledge of craft and invention, including smith deities like Gond, Reorx, Onatar, Moradin, Hephaestus, and Goibhniu.\nAt each indicated cleric level, you add the listed spells to your spells prepared.\nKnowledge Domain Spells\n1st | command, identify\n3rd | augury, suggestion\n5th | nondetection, speak with dead\n7th | arcane eye, confusion\n9th | legend lore, scrying" },
            { name: "Channel Divinity: Read Thoughts", level: 6, description: "At 6th level, you can use your Channel Divinity to read a creature's thoughts. You can then use your access to the creature's mind to command it.\nAs an action, choose one creature that you can see within 60 feet of you. That creature must make a Wisdom saving throw. If the creature succeeds on the saving throw, you can't use this feature on it again until you finish a long rest.\nIf the creature fails its save, you can read its surface thoughts (those foremost in its mind, reflecting its current emotions and what it is actively thinking about) when it is within 60 feet of you. This effect lasts for 1 minute.\nDuring that time, you can use your action to end this effect and cast the suggestion spell on the creature without expending a spell slot. The target automatically fails its saving throw against the spell." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Potent Spellcasting feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Potent Spellcasting", level: 8, description: "Starting at 8th level, you add your Wisdom modifier to the damage you deal with any cleric cantrip." },
            { name: "Visions of the Past", level: 17, description: "Starting at 17th level, you can call up visions of the past that relate to an object you hold or your immediate surroundings. You spend at least 1 minute in meditation and prayer, then receive dreamlike, shadowy glimpses of recent events. You can meditate in this way for a number of minutes equal to your Wisdom score and must maintain concentration during that time, as if you were casting a spell.\nOnce you use this feature, you can't use it again until you finish a short or long rest.\nObject Reading: Holding an object as you meditate, you can see visions of the object's previous owner. After meditating for 1 minute, you learn how the owner acquired and lost the object, as well as the most recent significant event involving the object and that owner. If the object was owned by another creature in the recent past (within a number of days equal to your Wisdom score), you can spend 1 additional minute for each owner to learn the same information about that creature.\nArea Reading: As you meditate, you see visions of recent events in your immediate vicinity (a room, street, tunnel, clearing, or the like, up to a 50-foot cube), going back a number of days equal to your Wisdom score. For each minute you meditate, you learn about one significant event, beginning with the most recent. Significant events typically involve powerful emotions, such as battles and betrayals, marriages and murders, births and funerals. However, they might also include more mundane events that are nevertheless important in your current situation." },
        ],
    },
    {
        name: "Knowledge Domain (PSA)",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Kefnet's task is to pass on this teaching of the God-Pharaoh and elucidate its meaning. He teaches that the afterlife will be inhabited only by those who have proved by their wits that they are worthy of dwelling in the glorious presence of the God-Pharaoh. He trains acolytes and initiates to push their limits and challenge their mental capacity with spells of ever-greater power.",
        features: [
            { name: "Knowledge Domain (PSA)", level: 3, description: "The worthy shall cultivate a nimble mind that can perceive the wonders beyond imagination that wait in the afterlife.\nKefnet's task is to pass on this teaching of the God-Pharaoh and elucidate its meaning. He teaches that the afterlife will be inhabited only by those who have proved by their wits that they are worthy of dwelling in the glorious presence of the God-Pharaoh. He trains acolytes and initiates to push their limits and challenge their mental capacity with spells of ever-greater power.\nKefnet's domain is identical to the Cleric." },
        ],
    },
    {
        name: "Life Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 3,
        description: "The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing, using that life force to cure many hurts.",
        features: [
            { name: "Disciple of Life", level: 3, description: "When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot's level." },
            { name: "Life Domain Spells", level: 3, description: "Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared.\nLife Domain Spells\n3rd | Aid, Bless, Cure Wounds, Lesser Restoration\n5th | Mass Healing Word, Revivify\n7th | Aura of Life, Death Ward\n9th | Greater Restoration, Mass Cure Wounds" },
            { name: "Preserve Life", level: 3, description: "As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Points maximum." },
            { name: "Blessed Healer", level: 6, description: "The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot's level." },
            { name: "Supreme Healing", level: 17, description: "When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don't roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12." },
        ],
    },
    {
        name: "Light Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 3,
        description: "The Light Domain emphasizes the divine power to bring about blazing fire and revelation. Clerics who wield this power are enlightened souls infused with radiance and the power of their deities' discerning vision, charged with chasing away lies and burning away darkness.",
        features: [
            { name: "Light Domain Spells", level: 3, description: "Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Light Domain Spells table, you thereafter always have the listed spells prepared.\nLight Domain Spells\n3rd | Burning Hands, Faerie Fire, Scorching Ray, See Invisibility\n5th | Daylight, Fireball\n7th | Arcane Eye, Wall of Fire\n9th | Flame Strike, Scrying" },
            { name: "Radiance of the Dawn", level: 3, description: "As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to emit a flash of light in a 30-foot Emanation [Area of Effect] originating from yourself. Any magical Darkness—such as that created by the Darkness spell—in that area is dispelled. Additionally, each creature of your choice in that area must make a Constitution saving throw, taking Radiant damage equal to 2d10 plus your Cleric level on a failed save or half as much damage on a successful one." },
            { name: "Warding Flare", level: 3, description: "When a creature that you can see within 30 feet of yourself makes an attack roll, you can take a Reaction to impose Disadvantage on the attack roll, causing light to flare before it hits or misses.\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a Long Rest." },
            { name: "Improved Warding Flare", level: 6, description: "You regain all expended uses of your Warding Flare when you finish a Short Rest or Long Rest.\nIn addition, whenever you use Warding Flare, you can give the target of the triggering attack a number of Temporary Hit Points equal to 2d6 plus your Wisdom modifier." },
            { name: "Corona of Light", level: 17, description: "As a Magic action, you cause yourself to emit an aura of sunlight that lasts for 1 minute or until you dismiss it (no action required). You emit Bright Light in a 60-foot radius and Dim Light for an additional 30 feet. Your enemies in the Bright Light have Disadvantage on saving throws against your Radiance of the Dawn and any spell that deals Fire or Radiant damage.\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest." },
        ],
    },
    {
        name: "Nature Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Gods of nature are as varied as the natural world itself, from inscrutable gods of the deep forests (such as Silvanus, Obad-Hai, Chislev, Balinor, and Pan) to friendly deities associated with particular springs and groves (such as Eldath). Druids revere nature as a whole and might serve one of these deities, practicing mysterious rites and reciting all-but-forgotten prayers in their own secret tongue. But many of these gods have clerics as well, champions who take a more active role in advancing the interests of a particular nature god. These clerics might hunt the evil monstrosities that despoil the woodlands, bless the harvest of the faithful, or wither the crops of those who anger their gods.",
        features: [
            { name: "Acolyte of Nature", level: 1, description: "At 1st level, you learn one druid cantrip of your choice. This cantrip doesn't count against the number of cleric cantrips you know. You also gain proficiency in one of the following skills of your choice: Animal Handling, Nature, or Survival." },
            { name: "Bonus Proficiency", level: 1, description: "Also at 1st level, you gain proficiency with heavy armor." },
            { name: "Channel Divinity: Charm Animals and Plants", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to charm animals and plants.\nAs an action, you present your holy symbol and invoke the name of your deity. Each beast or plant creature that can see you within 30 feet of you must make a Wisdom saving throw. If the creature fails its saving throw, it is charmed by you for 1 minute or until it takes damage. While it is charmed by you, it is friendly to you and other creatures you designate." },
            { name: "Channel Divinity: Charm Animals and Plants", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to charm animals and plants.\nAs an action, you present your holy symbol and invoke the name of your deity. Each beast or plant creature that can see you within 30 feet of you must make a Wisdom saving throw. If the creature fails its saving throw, it is charmed by you for 1 minute or until it takes damage. While it is charmed by you, it is friendly to you and other creatures you designate." },
            { name: "Nature Domain", level: 3, description: "Gods of nature are as varied as the natural world itself, from inscrutable gods of the deep forests (such as Silvanus, Obad-Hai, Chislev, Balinor, and Pan) to friendly deities associated with particular springs and groves (such as Eldath). Druids revere nature as a whole and might serve one of these deities, practicing mysterious rites and reciting all-but-forgotten prayers in their own secret tongue. But many of these gods have clerics as well, champions who take a more active role in advancing the interests of a particular nature god. These clerics might hunt the evil monstrosities that despoil the woodlands, bless the harvest of the faithful, or wither the crops of those who anger their gods.\nAt each indicated cleric level, you add the listed spells to your spells prepared.\nNature Domain Spells\n1st | animal friendship, speak with animals\n3rd | barkskin, spike growth\n5th | plant growth, wind wall\n7th | dominate beast, grasping vine\n9th | insect plague, tree stride" },
            { name: "Dampen Elements", level: 6, description: "Starting at 6th level, when you or a creature within 30 feet of you takes acid, cold, fire, lightning, or thunder damage, you can use your reaction to grant resistance to the creature against that instance of the damage." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 cold, fire, or lightning damage (your choice) to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Master of Nature", level: 17, description: "At 17th level, you gain the ability to command animals and plant creatures. While creatures are charmed by your Charm Animals and Plants feature, you can take a bonus action on your turn to verbally command what each of those creatures will do on its next turn." },
        ],
    },
    {
        name: "Order Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The Order Domain represents discipline, as well as devotion to a society or an institution and strict obedience to the laws governing it. On Ravnica, the domain is favored by clerics of the Azorius Senate, who use it to maintain and enforce the law, and of the Orzhov Syndicate, who exploit law and order for their personal gain. On other worlds, gods who grant access to this domain include Bane, Tyr, Majere, Erathis, Pholtus, Wee Jas, Aureon, Maglubiyet, Nuada, Athena, Anubis, Forseti, and Asmodeus.",
        features: [
            { name: "Bonus Proficiencies", level: 1, description: "When you choose this domain at 1st level, you gain proficiency with heavy armor. You also gain proficiency in the Intimidation or Persuasion skill (your choice)." },
            { name: "Voice of Authority", level: 1, description: "Starting at 1st level, you can invoke the power of law to drive an ally to attack. If you cast a spell with a spell slot of 1st level or higher and target an ally with the spell, that ally can use their reaction immediately after the spell to make one weapon attack against a creature of your choice that you can see.\nIf the spell targets more than one ally, you choose the ally who can make the attack." },
            { name: "Channel Divinity: Order's Demand", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to exert an intimidating presence over others.\nAs an action, you present your holy symbol, and each creature of your choice that can see or hear you within 30 feet of you must succeed on a Wisdom saving throw or be charmed by you until the end of your next turn or until the charmed creature takes any damage. You can also cause any of the charmed creatures to drop what they are holding when they fail the saving throw." },
            { name: "Channel Divinity: Order's Demand", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to exert an intimidating presence over others.\nAs an action, you present your holy symbol, and each creature of your choice that can see or hear you within 30 feet of you must succeed on a Wisdom saving throw or be charmed by you until the end of your next turn or until the charmed creature takes any damage. You can also cause any of the charmed creatures to drop what they are holding when they fail the saving throw." },
            { name: "Order Domain", level: 3, description: "The Order Domain represents discipline, as well as devotion to a society or an institution and strict obedience to the laws governing it. On Ravnica, the domain is favored by clerics of the Azorius Senate, who use it to maintain and enforce the law, and of the Orzhov Syndicate, who exploit law and order for their personal gain. On other worlds, gods who grant access to this domain include Bane, Tyr, Majere, Erathis, Pholtus, Wee Jas, Aureon, Maglubiyet, Nuada, Athena, Anubis, Forseti, and Asmodeus.\nThe ideal of order is obedience to the law above all else, rather than to a specific individual or the passing influence of emotion or popular rule. Clerics of order are typically concerned with how things are done, rather than whether an action's results are just. Following the law and obeying its edicts is critical, especially when it benefits these clerics and their guilds or deities.\nLaw establishes hierarchies. Those selected by the law to lead must be obeyed. Those who obey must do so to the best of their ability. In this manner, law creates an intricate web of obligations that allows society to forge order and security in a chaotic multiverse.\nAt each indicated cleric level, you add the listed spells to your spells prepared.\nOrder Domain Spells\n1st | command, heroism\n3rd | hold person, zone of truth\n5th | mass healing word, slow\n7th | compulsion, locate creature\n9th | commune, dominate person" },
            { name: "Embodiment of the Law", level: 6, description: "At 6th level, you become remarkably adept at channeling magical energy to compel others.\nIf you cast a spell of the enchantment school using a spell slot of 1st level or higher, you can change the spell's casting time to 1 bonus action for this casting, provided the spell's casting time is normally 1 action.\nYou can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses of it when you finish a long rest." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 psychic damage to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Order's Wrath", level: 17, description: "Starting at 17th level, enemies you designate for destruction wilt under the combined efforts of you and your allies. If you deal your Divine Strike damage to a creature on your turn, you can curse that creature until the start of your next turn. The next time one of your allies hits the cursed creature with an attack, the target also takes 2d8 psychic damage, and the curse ends. You can curse a creature in this way only once per turn." },
        ],
    },
    {
        name: "Peace Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The balm of peace thrives at the heart of healthy communities, between friendly nations, and in the souls of the kindhearted. The gods of peace inspire people of all sorts to resolve conflict and to stand up against those forces that try to prevent peace from flourishing. See the Peace Deities table for a list of some of the gods associated with this domain.",
        features: [
            { name: "Emboldening Bond", level: 1, description: "1st-level Peace Domain feature\nYou can forge an empowering bond among people who are at peace with one another. As an action, you choose a number of willing creatures within 30 feet of you (this can include yourself) equal to your proficiency bonus. You create a magical bond among them for 10 minutes or until you use this feature again. While any bonded creature is within 30 feet of another, the creature can roll a d4 and add the number rolled to an attack roll, an ability check, or a saving throw it makes. Each creature can add the d4 no more than once per turn.\nYou can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest." },
            { name: "Implement of Peace", level: 1, description: "1st-level Peace Domain feature\nYou gain proficiency in the Insight, Performance, or Persuasion skill (your choice)." },
            { name: "Channel Divinity: Balm of Peace", level: 2, description: "2nd-level Peace Domain feature\nYou can use your Channel Divinity to make your very presence a soothing balm. As an action, you can move up to your speed, without provoking opportunity attacks, and when you move within 5 feet of any other creature during this action, you can restore a number of hit points to that creature equal to 2d6 + your Wisdom modifier (minimum of 1 hit point). A creature can receive this healing only once whenever you take this action." },
            { name: "Channel Divinity: Balm of Peace", level: 3, description: "2nd-level Peace Domain feature\nYou can use your Channel Divinity to make your very presence a soothing balm. As an action, you can move up to your speed, without provoking opportunity attacks, and when you move within 5 feet of any other creature during this action, you can restore a number of hit points to that creature equal to 2d6 + your Wisdom modifier (minimum of 1 hit point). A creature can receive this healing only once whenever you take this action." },
            { name: "Peace Domain", level: 3, description: "The balm of peace thrives at the heart of healthy communities, between friendly nations, and in the souls of the kindhearted. The gods of peace inspire people of all sorts to resolve conflict and to stand up against those forces that try to prevent peace from flourishing. See the Peace Deities table for a list of some of the gods associated with this domain.\nClerics of the Peace Domain preside over the signing of treaties, and they are often asked to arbitrate in disputes. These clerics' blessings draw people together and help them shoulder one another's burdens, and the clerics' magic aids those who are driven to fight for the way of peace.\nPeace Deities\nAngharradh | Elven\nBerronar Truesilver | Dwarven\nBoldrei | Eberron\nCyrrollalee | Halfling\nEldath | Forgotten Realms\nGaerdal Ironhand | Gnomish\nPaladine | Dragonlance\nRao | Greyhawk\nDomain Spells: 1st-level Peace Domain feature\nYou gain domain spells at the cleric levels listed in the Peace Domain Spells table. See the Divine Domain class feature for how domain spells work.\nPeace Domain Spells\n1st | heroism, sanctuary\n3rd | aid, warding bond\n5th | beacon of hope, sending\n7th | aura of purity, Otiluke's resilient sphere\n9th | greater restoration, Rary's telepathic bond" },
            { name: "Protective Bond", level: 6, description: "6th-level Peace Domain feature\nThe bond you forge between people helps them protect each other. When a creature affected by your Emboldening Bond feature is about to take damage, a second bonded creature within 30 feet of the first can use its reaction to teleport to an unoccupied space within 5 feet of the first creature. The second creature then takes all the damage instead." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Potent Spellcasting feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Potent Spellcasting", level: 8, description: "8th-level Peace Domain feature\nYou add your Wisdom modifier to the damage you deal with any cleric cantrip." },
            { name: "Expansive Bond", level: 17, description: "17th-level Peace Domain feature\nThe benefits of your Emboldening Bond and Protective Bond features now work when the creatures are within 60 feet of each other. Moreover, when a creature uses Protective Bond to take someone else's damage, the creature has resistance to that damage." },
        ],
    },
    {
        name: "Solidarity Domain (PSA)",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Oketra is charged with expounding upon this teaching of the God-Pharaoh, instilling in every initiate the virtue of solidarity. She forges each group of children into a crop of acolytes with just one purpose: to be judged worthy of a glorious afterlife. And she instills in each crop the ability to unite in a single action in pursuit of that purpose. She is fond of poetic imagery to communicate her ideals.",
        features: [
            { name: "Bonus Proficiency", level: 1, description: "When you choose this domain at 1st level, you gain proficiency with heavy armor." },
            { name: "Solidarity's Action", level: 1, description: "Also at 1st level, when you take the Help action to aid an ally's attack, you can make one weapon attack as a bonus action. You can use this feature a number of times equal to your Wisdom modifier (minimum of once). You regain expended uses when you finish a long rest." },
            { name: "Channel Divinity: Preserve Life", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to heal the badly injured.\nAs an action, you present your holy symbol and evoke healing energy that can restore a number of hit points equal to five times your cleric level. Choose any creatures within 30 feet of you, and divide those hit points among them. This feature can restore a creature to no more than half of its hit point maximum. You can't use this feature on an undead or a construct." },
            { name: "Channel Divinity: Preserve Life", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to heal the badly injured.\nAs an action, you present your holy symbol and evoke healing energy that can restore a number of hit points equal to five times your cleric level. Choose any creatures within 30 feet of you, and divide those hit points among them. This feature can restore a creature to no more than half of its hit point maximum. You can't use this feature on an undead or a construct." },
            { name: "Solidarity Domain (PSA)", level: 3, description: "The worthy must know and respect all others whom the God-Pharaoh deems worthy, for in the afterlife, all will be united in purpose and action.\nOketra is charged with expounding upon this teaching of the God-Pharaoh, instilling in every initiate the virtue of solidarity. She forges each group of children into a crop of acolytes with just one purpose: to be judged worthy of a glorious afterlife. And she instills in each crop the ability to unite in a single action in pursuit of that purpose. She is fond of poetic imagery to communicate her ideals.\nAt each indicated cleric level, add the listed spells to your spells prepared.\nSolidarity Domain Spells\n1st | bless, guiding bolt\n3rd | aid, warding bond\n5th | beacon of hope, crusader's mantle\n7th | aura of life, guardian of faith\n9th | circle of power, mass cure wounds" },
            { name: "Oketra's Blessing", level: 6, description: "At 6th level, when a creature within 30 feet of you makes an attack roll, you can use your reaction to grant that creature a +10 bonus to the roll, using your Channel Divinity. You make this choice after you see the roll, but before the DM says whether the attack hits or misses." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 damage of the same type dealt by the weapon to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Supreme Healing", level: 17, description: "Starting at 17th level, when you would normally roll one or more dice to restore hit points with a spell, you instead use the highest number possible for each die. For example, instead of restoring 2d6 hit points to a creature, you restore 12." },
        ],
    },
    {
        name: "Strength Domain (PSA)",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "It falls to Rhonas to instill this teaching in those who would enter the afterlife—but to his mind, the words themselves don't matter. Strength can't be taught. It must be built through practice and training. Rhonas demonstrates his teachings by his example, rather than by giving his students any kind of academic instruction. He welcomes the people of Naktamun to stand by the Hekma and watch him as he storms into the desert to battle the greatest horrors. He encourages them to observe his indomitable strength, for though they will never equal it, they can aspire to mimicry. He invites them to scrutinize every move and practice what they see.",
        features: [
            { name: "Acolyte of Strength", level: 1, description: "At 1st level, you learn one druid cantrip of your choice. You also gain proficiency in one of the following skills of your choice: Animal Handling, Athletics, Nature, or Survival." },
            { name: "Bonus Proficiency", level: 1, description: "Also at 1st level, you gain proficiency with heavy armor." },
            { name: "Channel Divinity: Feat of Strength", level: 2, description: "At 2nd level, you can use your Channel Divinity to enhance your physical might. When you make an attack roll, ability check, or saving throw using Strength, you can use your Channel Divinity to gain a +10 bonus to the roll. You make this choice after you see the roll, but before the DM says whether the roll succeeds or fails." },
            { name: "Channel Divinity: Feat of Strength", level: 3, description: "At 2nd level, you can use your Channel Divinity to enhance your physical might. When you make an attack roll, ability check, or saving throw using Strength, you can use your Channel Divinity to gain a +10 bonus to the roll. You make this choice after you see the roll, but before the DM says whether the roll succeeds or fails." },
            { name: "Strength Domain (PSA)", level: 3, description: "The worthy shall hone a strong body that can withstand the boundless energies of the afterlife.\nIt falls to Rhonas to instill this teaching in those who would enter the afterlife—but to his mind, the words themselves don't matter. Strength can't be taught. It must be built through practice and training. Rhonas demonstrates his teachings by his example, rather than by giving his students any kind of academic instruction. He welcomes the people of Naktamun to stand by the Hekma and watch him as he storms into the desert to battle the greatest horrors. He encourages them to observe his indomitable strength, for though they will never equal it, they can aspire to mimicry. He invites them to scrutinize every move and practice what they see.\nAt each indicated cleric level, add the listed spells to your spells prepared.\nStrength Domain Spells\n1st | divine favor, shield of faith\n3rd | enhance ability, protection from poison\n5th | haste, protection from energy\n7th | dominate beast, stoneskin\n9th | destructive wave, insect plague" },
            { name: "Rhonas's Blessing", level: 6, description: "At 6th level, when a creature within 30 feet of you makes an attack roll, ability check, or saving throw using Strength, you can use your reaction to grant that creature a +10 bonus to the roll, using your Channel Divinity. You make this choice after you see the roll, but before the DM says whether the roll succeeds or fail." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 damage of the same type dealt by the weapon to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Avatar of Battle", level: 17, description: "At 17th level, you gain resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks." },
        ],
    },
    {
        name: "Tempest Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "Gods whose portfolios include the Tempest domain—including Talos, Umberlee, Kord, Zeboim, the Devourer, Zeus, and Thor—govern storms, sea, and sky. They include gods of lightning and thunder, gods of earthquakes, some fire gods, and certain gods of violence, physical strength, and courage. In some pantheons, a god of this domain rules over other deities and is known for swift justice delivered by thunderbolts. In the pantheons of seafaring people, gods of this domain are ocean deities and the patrons of sailors. Tempest gods send their clerics to inspire fear in the common folk, either to keep those folk on the path of righteousness or to encourage them to offer sacrifices of propitiation to ward off divine wrath.",
        features: [
            { name: "Bonus Proficiencies", level: 1, description: "At 1st level, you gain proficiency with martial weapons and heavy armor." },
            { name: "Wrath of the Storm", level: 1, description: "Also at 1st level, you can thunderously rebuke attackers. When a creature within 5 feet of you that you can see hits you with an attack, you can use your reaction to cause the creature to make a Dexterity saving throw. The creature takes 2d8 lightning or thunder damage (your choice) on a failed saving throw, and half as much damage on a successful one.\nYou can use this feature a number of times equal to your Wisdom modifier (a minimum of once). You regain all expended uses when you finish a long rest." },
            { name: "Channel Divinity: Destructive Wrath", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to wield the power of the storm with unchecked ferocity.\nWhen you roll lightning or thunder damage, you can use your Channel Divinity to deal maximum damage, instead of rolling." },
            { name: "Channel Divinity: Destructive Wrath", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to wield the power of the storm with unchecked ferocity.\nWhen you roll lightning or thunder damage, you can use your Channel Divinity to deal maximum damage, instead of rolling." },
            { name: "Tempest Domain", level: 3, description: "Gods whose portfolios include the Tempest domain—including Talos, Umberlee, Kord, Zeboim, the Devourer, Zeus, and Thor—govern storms, sea, and sky. They include gods of lightning and thunder, gods of earthquakes, some fire gods, and certain gods of violence, physical strength, and courage. In some pantheons, a god of this domain rules over other deities and is known for swift justice delivered by thunderbolts. In the pantheons of seafaring people, gods of this domain are ocean deities and the patrons of sailors. Tempest gods send their clerics to inspire fear in the common folk, either to keep those folk on the path of righteousness or to encourage them to offer sacrifices of propitiation to ward off divine wrath.\nAt each indicated cleric level, you add the listed spells to your spells prepared.\nTempest Domain Spells\n1st | fog cloud, thunderwave\n3rd | gust of wind, shatter\n5th | call lightning, sleet storm\n7th | control water, ice storm\n9th | destructive wave, insect plague" },
            { name: "Thunderbolt Strike", level: 6, description: "At 6th level, when you deal lightning damage to a Large or smaller creature, you can also push it up to 10 feet away from you." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 thunder damage to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Stormborn", level: 17, description: "At 17th level, you have a flying speed equal to your current walking speed whenever you are not underground or indoors." },
        ],
    },
    {
        name: "Trickery Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 3,
        description: "The Trickery Domain offers magic of deception, illusion, and stealth. Clerics who wield this magic are a disruptive force in the world, puncturing pride, mocking tyrants, freeing captives, and flouting hollow traditions. They prefer subterfuge and pranks to direct confrontation.",
        features: [
            { name: "Blessing of the Trickster", level: 3, description: "As a Magic action, you can choose yourself or a willing creature within 30 feet of yourself to have Advantage on Dexterity (Stealth) checks. This blessing lasts until you finish a Long Rest or you use this feature again." },
            { name: "Invoke Duplicity", level: 3, description: "As a Bonus Action, you can expend one use of your Channel Divinity to create a perfect visual illusion of yourself in an unoccupied space you can see within 30 feet of yourself. The illusion is intangible and doesn't occupy its space. It lasts for 1 minute, but it ends early if you dismiss it (no action required) or have the Incapacitated condition. The illusion is animated and mimics your expressions and gestures. While it persists, you gain the following benefits.\nCast Spells: You can cast spells as though you were in the illusion's space, but you must use your own senses.\nDistract: When both you and your illusion are within 5 feet of a creature that can see the illusion, you have Advantage on attack rolls against that creature, given how distracting the illusion is to the target.\nMove: As a Bonus Action, you can move the illusion up to 30 feet to an unoccupied space you can see that is within 120 feet of yourself." },
            { name: "Trickery Domain Spells", level: 3, description: "Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Trickery Domain Spells table, you thereafter always have the listed spells prepared.\nTrickery Domain Spells\n3rd | Charm Person, Disguise Self, Invisibility, Pass without Trace\n5th | Hypnotic Pattern, Nondetection\n7th | Confusion, Dimension Door\n9th | Dominate Person, Modify Memory" },
            { name: "Trickster's Transposition", level: 6, description: "Whenever you take the Bonus Action to create or move the illusion of your Invoke Duplicity, you can teleport, swapping places with the illusion." },
            { name: "Improved Duplicity", level: 17, description: "The illusion of your Invoke Duplicity has grown more powerful in the following ways.\nShared Distraction: When you and your allies make attack rolls against a creature within 5 feet of the illusion, the attack rolls have Advantage.\nHealing Illusion: When the illusion ends, you or a creature of your choice within 5 feet of it regains a number of Hit Points equal to your Cleric level." },
        ],
    },
    {
        name: "Twilight Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The twilit transition from light into darkness often brings calm and even joy, as the day's labors end and the hours of rest begin. The darkness can also bring terrors, but the gods of twilight guard against the horrors of the night.",
        features: [
            { name: "Bonus Proficiencies", level: 1, description: "1st-level Twilight Domain feature\nYou gain proficiency with martial weapons and heavy armor." },
            { name: "Eyes of Night", level: 1, description: "1st-level Twilight Domain feature\nYou can see through the deepest gloom. You have darkvision out to a range of 300 feet. In that radius, you can see in dim light as if it were bright light and in darkness as if it were dim light.\nAs an action, you can magically share the darkvision of this feature with willing creatures you can see within 10 feet of you, up to a number of creatures equal to your Wisdom modifier (minimum of one creature). The shared darkvision lasts for 1 hour. Once you share it, you can't do so again until you finish a long rest, unless you expend a spell slot of any level to share it again." },
            { name: "Vigilant Blessing", level: 1, description: "1st-level Twilight Domain feature\nThe night has taught you to be vigilant. As an action, you give one creature you touch (including possibly yourself) advantage on the next initiative roll the creature makes. This benefit ends immediately after the roll or if you use this feature again." },
            { name: "Channel Divinity: Twilight Sanctuary", level: 2, description: "2nd-level Twilight Domain feature\nYou can use your Channel Divinity to refresh your allies with soothing twilight.\nAs an action, you present your holy symbol, and a sphere of twilight emanates from you. The sphere is centered on you, has a 30-foot radius, and is filled with dim light. The sphere moves with you, and it lasts for 1 minute or until you are incapacitated or die. Whenever a creature (including you) ends its turn in the sphere, you can grant that creature one of these benefits:\n- You grant it temporary hit points equal to 1d6 plus your cleric level.\n- You end one effect on it causing it to be charmed or frightened." },
            { name: "Channel Divinity: Twilight Sanctuary", level: 3, description: "2nd-level Twilight Domain feature\nYou can use your Channel Divinity to refresh your allies with soothing twilight.\nAs an action, you present your holy symbol, and a sphere of twilight emanates from you. The sphere is centered on you, has a 30-foot radius, and is filled with dim light. The sphere moves with you, and it lasts for 1 minute or until you are incapacitated or die. Whenever a creature (including you) ends its turn in the sphere, you can grant that creature one of these benefits:\n- You grant it temporary hit points equal to 1d6 plus your cleric level.\n- You end one effect on it causing it to be charmed or frightened." },
            { name: "Twilight Domain", level: 3, description: "The twilit transition from light into darkness often brings calm and even joy, as the day's labors end and the hours of rest begin. The darkness can also bring terrors, but the gods of twilight guard against the horrors of the night.\nClerics who serve these deities-examples of which appear on the Twilight Deities table-bring comfort to those who seek rest and protect them by venturing into the encroaching darkness to ensure that the dark is a comfort, not a terror.\nTwilight Deities\nBoldrei | Eberron\nCelestian | Greyhawk\nDol Arrah | Eberron\nHelm | Forgotten Realms\nIlmater | Forgotten Realms\nMishakal | Dragonlance\nSelûne | Forgotten Realms\nYondalla | Halfling\nDomain Spells: 1st-level Twilight Domain feature\nYou gain domain spells at the cleric levels listed in the Twilight Domain Spells table. See the Divine Domain class feature for how domain spells work.\nTwilight Domain Spells\n1st | faerie fire, sleep\n3rd | moonbeam, see invisibility\n5th | aura of vitality, Leomund's tiny hut\n7th | aura of life, greater invisibility\n9th | circle of power, mislead" },
            { name: "Steps of Night", level: 6, description: "6th-level Twilight Domain feature\nYou can draw on the mystical power of night to rise into the air. As a bonus action when you are in dim light or darkness, you can magically give yourself a flying speed equal to your walking speed for 1 minute. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "8th-level Twilight Domain feature\nYou gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Twilight Shroud", level: 17, description: "17th-level Twilight Domain feature\nThe twilight that you summon offers a protective embrace: you and your allies have Cover while in the sphere created by your Twilight Sanctuary." },
        ],
    },
    {
        name: "War Domain",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 3,
        description: "War has many manifestations. It can make heroes of ordinary people. It can be desperate and horrific, with acts of cruelty and cowardice eclipsing instances of excellence and courage. Clerics who tap into the magic of the War Domain excel in battle, inspiring others to fight the good fight or offering acts of violence as prayers.",
        features: [
            { name: "Guided Strike", level: 3, description: "When you or a creature within 30 feet of you misses with an attack roll, you can expend one use of your Channel Divinity and give that roll a +10 bonus, potentially causing it to hit. When you use this feature to benefit another creature's attack roll, you must take a Reaction to do so." },
            { name: "War Domain Spells", level: 3, description: "Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the War Domain Spells table, you thereafter always have the listed spells prepared.\nWar Domain Spells\n3rd | Guiding Bolt, Magic Weapon, Shield of Faith, Spiritual Weapon\n5th | Crusader's Mantle, Spirit Guardians\n7th | Fire Shield, Freedom of Movement\n9th | Hold Monster, Steel Wind Strike" },
            { name: "War Priest", level: 3, description: "As a Bonus Action, you can make one attack with a weapon or an Unarmed Strike. You can use this Bonus Action a number of times equal to your Wisdom modifier (minimum of once). You regain all expended uses when you finish a Short Rest or Long Rest." },
            { name: "War God's Blessing", level: 6, description: "You can expend a use of your Channel Divinity to cast Shield of Faith or Spiritual Weapon rather than expending a spell slot. When you cast either spell in this way, the spell doesn't require Concentration. Instead the spell lasts for 1 minute, but it ends early if you cast that spell again, have the Incapacitated condition, or die." },
            { name: "Avatar of Battle", level: 17, description: "You gain Resistance to Bludgeoning, Piercing, and Slashing damage." },
        ],
    },
    {
        name: "Zeal Domain (PSA)",
        parentClass: "Cleric",
        edition: "2024",
        grantedAtLevel: 1,
        description: "The God-Pharaoh expects those he welcomes into the afterlife to desire it above all other pleasures and achievements, and for them to show their dedication, passion, and fervor through their actions. Hazoret is charged with cultivating this zeal in the initiates who come under her care, and she has undertaken the task with appropriate enthusiasm. She recognizes, however, that the best way to teach zeal is by demonstrating it.",
        features: [
            { name: "Bonus Proficiencies", level: 1, description: "At 1st level, you gain proficiency with martial weapons and heavy armor." },
            { name: "Priest of Zeal", level: 1, description: "From 1st level, Hazoret delivers bolts of inspiration to you while you are engaged in battle. When you use the Attack action, you can make one weapon attack as a bonus action.\nYou can use this feature a number of times equal to your Wisdom modifier (a minimum of once). You regain all expended uses when you finish a long rest." },
            { name: "Channel Divinity: Consuming Fervor", level: 2, description: "Starting at 2nd level, you can use your Channel Divinity to channel your zeal into unchecked ferocity.\nWhen you roll fire or thunder damage, you can use your Channel Divinity to deal maximum damage instead of rolling." },
            { name: "Channel Divinity: Consuming Fervor", level: 3, description: "Starting at 2nd level, you can use your Channel Divinity to channel your zeal into unchecked ferocity.\nWhen you roll fire or thunder damage, you can use your Channel Divinity to deal maximum damage instead of rolling." },
            { name: "Zeal Domain (PSA)", level: 3, description: "The worthy shall rush to the God-Pharaoh's side with relentless zeal, rising to overcome every obstacle in their way.\nThe God-Pharaoh expects those he welcomes into the afterlife to desire it above all other pleasures and achievements, and for them to show their dedication, passion, and fervor through their actions. Hazoret is charged with cultivating this zeal in the initiates who come under her care, and she has undertaken the task with appropriate enthusiasm. She recognizes, however, that the best way to teach zeal is by demonstrating it.\nAt each indicated cleric level, add the listed spells to your spells prepared.\nZeal Domain Spells\n1st | searing smite, thunderous smite\n3rd | magic weapon, shatter\n5th | haste, fireball\n7th | fire shield, freedom of movement\n9th | destructive wave, flame strike" },
            { name: "Resounding Strike", level: 6, description: "At 6th level, when you deal thunder damage to a Large or smaller creature, you can also push it up to 10 feet away from you." },
            { name: "Blessed Strikes", level: 8, description: "8th-level cleric optional class features, which replaces the Divine Strike feature\nYou are blessed with divine might in battle. When a creature takes damage from one of your cantrips or weapon attacks, you can also deal 1d8 radiant damage to that creature. Once you deal this damage, you can't use this feature again until the start of your next turn." },
            { name: "Divine Strike", level: 8, description: "At 8th level, you gain the ability to infuse your weapon strikes with divine energy. Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 damage of the same type dealt by the weapon to the target. When you reach 14th level, the extra damage increases to 2d8." },
            { name: "Blaze of Glory", level: 17, description: "Starting at 17th level, you can delay death for an instant to perform a final heroic act.\nWhen you are reduced to 0 hit points by an attacker you can see, even if you would be killed outright, you can use your reaction to move up to your speed toward the attacker and make one melee weapon attack against it, as long as the movement brings it within your reach. You make this attack with advantage. If the attack hits, the creature takes an extra 5d10 fire damage and an extra 5d10 damage of the weapon's type. You then fall unconscious and begin making death saving throws as normal, or you die if the damage you took would have killed you outright.\nOnce you use this feature, you can't use it again until you finish a long rest." },
        ],
    },
];
